# Builds the complete evidence package (Parts 1-8) for the 4-anchor x 3-band
# grid (N=1344/1728/1920/2176 for 1/2/3/4 nodes), from the canonical
# throughput_raw.csv / masking_effectiveness.csv already regenerated by
# analysis/gather_metrics.R and analysis/masking_effectiveness.R.
#
# The 5-node anchor (N=2340, 2x2x5) was derived and added to
# g5k/csv/experimentos.csv, but the campaign itself has NOT run yet (blocked
# twice by the scheduler granting fewer than 5 chuc nodes) -- so 1:4 here is
# the current data reality, not a step back from the 5-node prep. Re-widen to
# 1:5 once bench_*_5n_20g_N2340 actually has done reps.
#
# Every number here is computed directly from measured per-rep data. No
# value is invented or estimated. Reps included: only checkpoint_status ==
# "done" for throughput; masking_effectiveness.csv has no separate status
# column (every row it emits is a rep with a valid dc.csv window).
suppressMessages(library(tidyverse))

set.seed(1) # not used for randomness; kept for reproducibility if extended
out_dir <- "analysis/results_package"
tab_dir <- file.path(out_dir, "tables")
fig_dir <- file.path(out_dir, "figures")

ANCHOR_N <- c(`1` = 1344, `2` = 1728, `3` = 1920, `4` = 2176)
GPUS_PER_NODE <- 4
BANDS <- c("1gbit", "10gbit", "25gbit")
BAND_LABEL <- c("1gbit" = "1 Gbit/s", "10gbit" = "10 Gbit/s", "25gbit" = "25 Gbit/s")
BAND_ORDER <- c("1gbit", "10gbit", "25gbit")

exp_id <- function(band, nodes) sprintf("bench_%s_%dn_%dg_N%d", band, nodes, nodes * GPUS_PER_NODE, ANCHOR_N[as.character(nodes)])

grid <- expand_grid(nodes = 1:4, band = BANDS) |>
  mutate(
    gpus = nodes * GPUS_PER_NODE,
    N = ANCHOR_N[as.character(nodes)],
    experiment_id = map2_chr(band, nodes, exp_id)
  )

# ---------------------------------------------------------------- raw loads
thr_raw <- read_csv("analysis/throughput_raw.csv", show_col_types = FALSE) |>
  filter(checkpoint_status == "done", experiment_id %in% grid$experiment_id)

me_raw <- read_csv("analysis/masking_effectiveness.csv", show_col_types = FALSE) |>
  filter(experiment_id %in% grid$experiment_id)

stopifnot(all(grid$experiment_id %in% thr_raw$experiment_id))
stopifnot(all(grid$experiment_id %in% me_raw$experiment_id))

ci95 <- function(x) {
  n <- length(x)
  if (n < 2) return(NA_real_)
  sd(x) / sqrt(n) * qt(0.975, df = n - 1)
}
cv_pct <- function(x) 100 * sd(x) / mean(x)

# =====================================================================
# PART 1 -- per-combination statistics
# =====================================================================
thr_stats <- thr_raw |>
  group_by(experiment_id) |>
  summarise(
    n = n(), mean_msamples = mean(msamples_per_s), sd_msamples = sd(msamples_per_s),
    ci95_msamples = ci95(msamples_per_s), min_msamples = min(msamples_per_s), max_msamples = max(msamples_per_s),
    cv_msamples_pct = cv_pct(msamples_per_s),
    mean_total_time_s = mean(total_time), sd_total_time_s = sd(total_time),
    ci95_total_time_s = ci95(total_time), min_total_time_s = min(total_time), max_total_time_s = max(total_time),
    cv_total_time_pct = cv_pct(total_time),
    .groups = "drop"
  )

me_stats <- me_raw |>
  group_by(experiment_id) |>
  summarise(
    n_me = n(), mean_me = mean(masking_effectiveness), sd_me = sd(masking_effectiveness),
    ci95_me = ci95(masking_effectiveness), min_me = min(masking_effectiveness), max_me = max(masking_effectiveness),
    cv_me_pct = cv_pct(masking_effectiveness),
    .groups = "drop"
  )

part1 <- grid |>
  left_join(thr_stats, by = "experiment_id") |>
  left_join(me_stats, by = "experiment_id") |>
  arrange(nodes, factor(band, levels = BAND_ORDER))

write_csv(part1, file.path(tab_dir, "part1_statistics.csv"))

# =====================================================================
# PART 2 -- per-topology band-to-band gains (throughput and ME)
# =====================================================================
gain_pct <- function(a, b) 100 * (b - a) / a # a -> b

part2 <- grid |>
  select(nodes, band) |>
  left_join(part1 |> select(nodes, band, mean_msamples, mean_me), by = c("nodes", "band")) |>
  pivot_wider(id_cols = nodes, names_from = band, values_from = c(mean_msamples, mean_me)) |>
  mutate(
    thr_gain_1to10_pct  = gain_pct(mean_msamples_1gbit, mean_msamples_10gbit),
    thr_gain_10to25_pct = gain_pct(mean_msamples_10gbit, mean_msamples_25gbit),
    thr_gain_1to25_pct  = gain_pct(mean_msamples_1gbit, mean_msamples_25gbit),
    thr_diminishing_returns_pct = 100 * thr_gain_10to25_pct / thr_gain_1to10_pct,
    me_gain_1to10_pct  = gain_pct(mean_me_1gbit, mean_me_10gbit),
    me_gain_10to25_pct = gain_pct(mean_me_10gbit, mean_me_25gbit),
    me_gain_1to25_pct  = gain_pct(mean_me_1gbit, mean_me_25gbit),
    me_diminishing_returns_pct = 100 * me_gain_10to25_pct / me_gain_1to10_pct,
    me_gain_1to10_pp  = 100 * (mean_me_10gbit - mean_me_1gbit),
    me_gain_10to25_pp = 100 * (mean_me_25gbit - mean_me_10gbit),
    me_gain_1to25_pp  = 100 * (mean_me_25gbit - mean_me_1gbit)
  )

write_csv(part2, file.path(tab_dir, "part2_band_gains.csv"))

# =====================================================================
# PART 3 -- cross-scale comparison (1->2->3->4 nodes), per band
# =====================================================================
part3_base <- grid |>
  select(nodes, band, gpus) |>
  left_join(part1 |> select(nodes, band, mean_msamples, mean_me), by = c("nodes", "band")) |>
  mutate(throughput_per_gpu = mean_msamples / gpus) |>
  arrange(factor(band, levels = BAND_ORDER), nodes)

part3_steps <- part3_base |>
  group_by(band) |>
  arrange(nodes, .by_group = TRUE) |>
  mutate(
    step = paste0(lag(nodes), "->", nodes),
    thr_per_gpu_prev = lag(throughput_per_gpu),
    thr_per_gpu_pct_change = 100 * (throughput_per_gpu - thr_per_gpu_prev) / thr_per_gpu_prev,
    thr_per_gpu_abs_diff = throughput_per_gpu - thr_per_gpu_prev,
    me_prev = lag(mean_me),
    me_pct_change = 100 * (mean_me - me_prev) / me_prev,
    me_abs_diff_pp = 100 * (mean_me - me_prev)
  ) |>
  filter(!is.na(thr_per_gpu_prev)) |>
  select(band, step, throughput_per_gpu, thr_per_gpu_pct_change, thr_per_gpu_abs_diff,
         mean_me, me_pct_change, me_abs_diff_pp) |>
  ungroup()

slope_of <- function(y, x) coef(lm(y ~ x))[["x"]]
r2_of <- function(y, x) summary(lm(y ~ x))$r.squared

part3_slopes <- part3_base |>
  group_by(band) |>
  summarise(
    slope_throughput_per_gpu_per_node = slope_of(throughput_per_gpu, nodes),
    r2_throughput_per_gpu_vs_nodes = r2_of(throughput_per_gpu, nodes),
    slope_me_pp_per_node = slope_of(100 * mean_me, nodes),
    r2_me_vs_nodes = r2_of(mean_me, nodes),
    .groups = "drop"
  )

write_csv(part3_base, file.path(tab_dir, "part3_scaling_raw.csv"))
write_csv(part3_steps, file.path(tab_dir, "part3_scaling_steps.csv"))
write_csv(part3_slopes, file.path(tab_dir, "part3_scaling_slopes.csv"))

# =====================================================================
# PART 4 -- descriptive, data-derived trend statements (no interpretation)
# =====================================================================
trend_lines <- c()
add <- function(x) trend_lines <<- c(trend_lines, x)

# Amplitude (max-min across bands) per topology, for ME and throughput
amp <- part1 |>
  group_by(nodes) |>
  summarise(
    me_min = min(mean_me), me_max = max(mean_me), me_amplitude_pp = 100 * (me_max - me_min),
    thr_min = min(mean_msamples), thr_max = max(mean_msamples),
    thr_amplitude_pct_of_min = 100 * (thr_max - thr_min) / thr_min,
    max_ci95_me_pp = 100 * max(ci95_me, na.rm = TRUE),
    .groups = "drop"
  )
write_csv(amp, file.path(tab_dir, "part4_amplitude_by_topology.csv"))

add(sprintf(
  "Amplitude de Masking Effectiveness entre bandas, por topologia (pp = pontos percentuais): %s",
  paste(sprintf("%d nó(s)=%.1fpp", amp$nodes, amp$me_amplitude_pp), collapse = "; ")
))
add(sprintf(
  "Maior IC95 individual de ME (pp) por topologia, para referencia de ruido de medicao: %s",
  paste(sprintf("%d nó(s)=%.2fpp", amp$nodes, amp$max_ci95_me_pp), collapse = "; ")
))
first_above_noise <- amp |> filter(me_amplitude_pp > max_ci95_me_pp) |> slice(1)
add(sprintf(
  "Primeira topologia em que a amplitude de ME entre bandas excede o maior IC95 individual observado naquela topologia: %d nó(s) (amplitude=%.1fpp > IC95=%.2fpp)",
  first_above_noise$nodes[1], first_above_noise$me_amplitude_pp[1], first_above_noise$max_ci95_me_pp[1]
))

amp_ord <- amp |> arrange(nodes)
step_growth <- diff(amp_ord$me_amplitude_pp)
add(sprintf(
  "Variacao da amplitude de ME (pp) de uma topologia para a seguinte: %s",
  paste(sprintf("%d->%d nós: %+.1fpp", amp_ord$nodes[-4], amp_ord$nodes[-1], step_growth), collapse = "; ")
))
add(sprintf(
  "Maior crescimento de amplitude ocorre no passo %d->%d nós (%+.1fpp)",
  amp_ord$nodes[-4][which.max(step_growth)], amp_ord$nodes[-1][which.max(step_growth)], max(step_growth)
))

# Linearity / saturation via step deltas already in part3_steps + slopes/R2
for (b in BAND_ORDER) {
  s <- part3_steps |> filter(band == b)
  add(sprintf(
    "[%s] Variacao percentual do throughput/GPU por passo de escala: %s",
    BAND_LABEL[b], paste(sprintf("%s: %+.1f%%", s$step, s$thr_per_gpu_pct_change), collapse = "; ")
  ))
  add(sprintf(
    "[%s] Variacao absoluta de ME (pp) por passo de escala: %s",
    BAND_LABEL[b], paste(sprintf("%s: %+.1fpp", s$step, s$me_abs_diff_pp), collapse = "; ")
  ))
}
add(sprintf(
  "R^2 do ajuste linear (throughput/GPU vs numero de nos) por banda: %s",
  paste(sprintf("%s=%.3f", BAND_LABEL[part3_slopes$band], part3_slopes$r2_throughput_per_gpu_vs_nodes), collapse = "; ")
))
add(sprintf(
  "R^2 do ajuste linear (ME vs numero de nos) por banda: %s",
  paste(sprintf("%s=%.3f", BAND_LABEL[part3_slopes$band], part3_slopes$r2_me_vs_nodes), collapse = "; ")
))

# Diminishing returns ratio already computed in part2; restate plainly
add(sprintf(
  "Razao (ganho 10->25) / (ganho 1->10), throughput, por topologia: %s",
  paste(sprintf("%d nó(s)=%.1f%%", part2$nodes, part2$thr_diminishing_returns_pct), collapse = "; ")
))
add(sprintf(
  "Razao (ganho 10->25) / (ganho 1->10), Masking Effectiveness, por topologia: %s",
  paste(sprintf("%d nó(s)=%.1f%%", part2$nodes, part2$me_diminishing_returns_pct), collapse = "; ")
))

# "Which band looks sufficient": 10gbit vs 25gbit delta relative to CI95
suff <- part1 |>
  filter(band %in% c("10gbit", "25gbit")) |>
  select(nodes, band, mean_me, ci95_me) |>
  pivot_wider(names_from = band, values_from = c(mean_me, ci95_me)) |>
  mutate(
    delta_me_pp = 100 * (mean_me_25gbit - mean_me_10gbit),
    max_ci95_pp = 100 * pmax(ci95_me_10gbit, ci95_me_25gbit, na.rm = TRUE),
    within_noise = abs(delta_me_pp) <= max_ci95_pp
  )
write_csv(suff, file.path(tab_dir, "part4_10gbit_vs_25gbit.csv"))
add(sprintf(
  "Diferenca de ME entre 10gbit e 25gbit (pp), por topologia, e se fica dentro do IC95: %s",
  paste(sprintf("%d nó(s): %+.2fpp (IC95max=%.2fpp, dentro=%s)", suff$nodes, suff$delta_me_pp, suff$max_ci95_pp, suff$within_noise), collapse = "; ")
))

# Order-inversion check: does 10gbit ever exceed 25gbit in mean value?
inv_thr <- part1 |>
  filter(band %in% c("10gbit", "25gbit")) |>
  select(nodes, band, mean_msamples) |>
  pivot_wider(names_from = band, values_from = mean_msamples) |>
  mutate(inversion = `10gbit` > `25gbit`, diff_msamples = `10gbit` - `25gbit`)
write_csv(inv_thr, file.path(tab_dir, "part4_order_inversion_10v25_throughput.csv"))
inv_rows <- inv_thr |> filter(inversion)
if (nrow(inv_rows) > 0) {
  add(sprintf(
    "Inversao de ordem (throughput 10gbit > 25gbit, valor medio) observada em: %s",
    paste(sprintf("%d nó(s) (10gbit=%.1f MSamples/s > 25gbit=%.1f MSamples/s, diff=%.1f)",
                   inv_rows$nodes, inv_rows$`10gbit`, inv_rows$`25gbit`, inv_rows$diff_msamples), collapse = "; ")
  ))
} else {
  add("Inversao de ordem (throughput 10gbit > 25gbit, valor medio): nao observada em nenhuma topologia.")
}

# Regime change: topology/band where mean_me crosses below 0.5
below_half <- part1 |> filter(mean_me < 0.5) |> arrange(nodes, factor(band, levels = BAND_ORDER))
add(sprintf(
  "Combinacoes (nos, banda) com Masking Effectiveness medio < 0.5: %s",
  if (nrow(below_half) == 0) "nenhuma" else paste(sprintf("%d nó(s)/%s (ME=%.3f)", below_half$nodes, BAND_LABEL[below_half$band], below_half$mean_me), collapse = "; ")
))

# Outlier detection: per experiment_id, per metric, |z| > 2 on raw per-rep values
outlier_scan <- function(df, id_col, val_col, label) {
  df |>
    group_by(.data[[id_col]]) |>
    mutate(z = (.data[[val_col]] - mean(.data[[val_col]])) / sd(.data[[val_col]])) |>
    ungroup() |>
    filter(abs(z) > 2) |>
    mutate(metric = label)
}
out_thr <- outlier_scan(thr_raw, "experiment_id", "msamples_per_s", "throughput_msamples") |>
  select(experiment_id, rep, value = msamples_per_s, z, metric)
out_me <- outlier_scan(me_raw, "experiment_id", "masking_effectiveness", "masking_effectiveness") |>
  select(experiment_id, rep, value = masking_effectiveness, z, metric)
outliers <- bind_rows(out_thr, out_me) |> arrange(experiment_id, metric)
write_csv(outliers, file.path(tab_dir, "part4_outliers_zscore_gt2.csv"))
add(sprintf(
  "Repeticoes com |z-score| > 2 dentro do proprio experiment_id (n=5, portanto criterio exploratorio, nao um teste formal): %s",
  if (nrow(outliers) == 0) "nenhuma detectada" else paste(sprintf("%s rep%d %s=%.4f (z=%.2f)", outliers$experiment_id, outliers$rep, outliers$metric, outliers$value, outliers$z), collapse = "; ")
))

writeLines(trend_lines, file.path(tab_dir, "part4_trends.txt"))
cat(paste(trend_lines, collapse = "\n\n"), "\n")
